54	 * point too: calling it from a constructor would itself be legal, but lazy
55	 * resolution keeps process startup identical to an un-preloaded run.
56	 */
57	static struct target g_target = {0, 0, 0, -1, 0};
58	static read_fn_t g_real_read;
59	static read_chk_fn_t g_real_read_chk;
