1	#include <cerrno>
2	#include <cstring>
3	#include <fcntl.h>
4	#include <iostream>
5	#include <memory>
6	#include <string>
7	#include <string_view>
8	#include <sys/stat.h>
9	#include <unistd.h>
10	#include <vector>
11	
12	#include <openssl/evp.h>
13	#include <openssl/x509.h>
14	
15	namespace {
16	
17	constexpr size_t kSha256Size = 32;
18	constexpr std::string_view kDigestPrefix = "sha256:";
19	constexpr size_t kDigestHexLen = 2 * kSha256Size;  // 64 lowercase hex chars
20	constexpr std::string_view kSpkiFingerprintPrefix = "spki-sha256:";
21	
22	constexpr std::string_view kPemBegin = "-----BEGIN PUBLIC KEY-----";
23	constexpr std::string_view kPemEnd = "-----END PUBLIC KEY-----";
24	
25	int printUsage() {
26	    std::cerr << "Usage: sealmark --version\n"
27	                 "       sealmark digest <file>\n"
28	                 "       sealmark verify-digest <file> <expected-digest>\n"
29	                 "       sealmark key-id <public-key-file>\n";
30	    return 2;
31	}
32	
33	// ASCII whitespace permitted around the PEM block: the standard C/POSIX set
34	// of horizontal tab, LF, vertical tab, form feed, CR and space (the bytes for
35	// which Python's bytes.isspace() is true within ASCII). Everything else --
36	// including non-ASCII bytes -- is significant content and causes rejection.
37	bool isAsciiSpace(unsigned char c) {
38	    return c == ' ' || (c >= '\t' && c <= '\r');
39	}
40	
41	// --- Shared regular-file reading ------------------------------------------
42	//
43	// digest, verify-digest and key-id all walk the same pipeline: open the
44	// input, require the object actually opened to be a regular file, then read
45	// its complete raw bytes from the start in fixed-size passes until normal
46	// EOF, treating text and binary content identically. The three only differ
47	// in what happens to each chunk, which is expressed by a ByteSink (see
48	// processFileChunks):
49	//   * digest / verify-digest stream the bytes straight into SHA-256, so their
50	//     memory use does not grow with the file;
51	//   * key-id runs a streaming PEM parser over the chunks: the surrounding
52	//     ASCII whitespace and the base64 text are consumed byte by byte without
53	//     being retained, and only the decoded SubjectPublicKeyInfo DER is kept,
54	//     so its memory use tracks the (small) public-key encoding rather than
55	//     the file size.
56	// The error reporting for the open, file-type and read stages lives here
57	// once; sinks report only their own processing failures.
58	
59	// Size of every read pass for all three commands.
60	constexpr size_t kReadChunkSize = 64 * 1024;
61	
62	// Opens pathArg and requires the object actually opened -- the final target
63	// of any symlink chain, examined on the open file descriptor itself -- to be
64	// a regular file. The descriptor is fstat()ed, not the path: opening and the
65	// type decision are one and the same object, so there is no window in which a
66	// path that named a regular file at check time could be swapped for a FIFO or
67	// other non-regular object before it is opened. A FIFO is opened with
68	// O_NONBLOCK so the open itself never blocks waiting for the other end; the
69	// descriptor is closed immediately after fstat() shows it is not regular, so
70	// a FIFO's data is never read and no FIFO read can ever block. Once a regular
71	// file is held open, later reads always refer to that same file even if the
72	// path is renamed or replaced afterwards.
73	//
74	// The two pre-read failure stages stay distinct: a failure to open the path
75	// ("cannot open", covering a path that vanished, a dangling symlink or a
76	// traversal/permission error) and an object that opened but is not a regular
77	// file ("is not a regular file"). On failure prints a reason containing
78	// pathArg to stderr, closes any descriptor it opened and returns -1.
79	int openRegularInput(const char* pathArg) {
80	    // O_NONBLOCK keeps an open() on a FIFO without a writer from blocking;
81	    // it has no effect on regular files. O_CLOEXEC does not change behavior
82	    // for this process but keeps the descriptor from leaking if a later
83	    // change ever execs.
84	    int fd = ::open(pathArg, O_RDONLY | O_NONBLOCK | O_CLOEXEC);
85	    if (fd < 0) {
86	        const int err = errno;
87	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
88	                  << std::strerror(err) << '\n';
89	        return -1;
90	    }
91	
92	    struct stat st {};
93	    if (::fstat(fd, &st) != 0) {
94	        const int err = errno;
95	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
96	                  << std::strerror(err) << '\n';
97	        ::close(fd);
98	        return -1;
99	    }
100	    if (!S_ISREG(st.st_mode)) {
101	        std::cerr << "sealmark: '" << pathArg
102	                  << "' is not a regular file\n";
103	        ::close(fd);
104	        return -1;
105	    }
106	    return fd;
107	}
108	
109	// Closes the descriptor on destruction, so every failure path below -- a
110	// failed start(), a rejected chunk or a read error -- releases it.
111	class FdGuard {
112	public:
113	    explicit FdGuard(int fd) : fd_(fd) {}
114	    ~FdGuard() {
115	        if (fd_ >= 0) {
116	            ::close(fd_);
117	        }
118	    }
119	    FdGuard(const FdGuard&) = delete;
120	    FdGuard& operator=(const FdGuard&) = delete;
121	
122	private:
123	    int fd_;
124	};
125	
126	// Feeds a regular file's complete raw bytes to sink:
127	//   start()             once, immediately after the file is opened;
128	//   consume(data, size) for every non-empty chunk, including a final short
129	//                       one (a zero-length file yields no consume() call);
130	//   finish()            exactly once, only after a read reaching normal EOF.
131	// A false return aborts the operation and the sink is responsible for its own
132	// diagnostic. read() on a regular file is allowed to return fewer bytes than
133	// requested without meaning EOF (an interrupt, a short kernel read, ...), so
134	// each pass keeps reading until the buffer fills or read() reports zero; only
135	// a zero return is normal EOF. A read error -- including one after some bytes
136	// were already delivered -- is reported as such and never reaches finish(), so
137	// a mid-read failure can never surface as a digest, a match/mismatch result
138	// or a key fingerprint.
139	template <typename ByteSink>
140	bool processFileChunks(const char* pathArg, ByteSink& sink) {
141	    const int openedFd = openRegularInput(pathArg);
142	    if (openedFd < 0) {
143	        return false;
144	    }
145	    FdGuard fdGuard(openedFd);
146	    if (!sink.start()) {
147	        return false;
148	    }
149	
150	    std::vector<char> buffer(kReadChunkSize);
151	    while (true) {
152	        size_t filled = 0;
153	        bool reachedEof = false;
154	        while (filled < buffer.size()) {
155	            ssize_t got = 0;
156	            do {
157	                got = ::read(openedFd, buffer.data() + filled,
158	                             buffer.size() - filled);
159	            } while (got < 0 && errno == EINTR);
160	            if (got < 0) {
161	                // The file was already opened successfully; this is a
162	                // read-stage failure, never an open error or a content/format
163	                // problem -- even if earlier bytes of this pass were already
164	                // delivered to the sink.
165	                std::cerr << "sealmark: failed to read '" << pathArg
166	                          << "'\n";
167	                return false;
168	            }
169	            if (got == 0) {
170	                reachedEof = true;  // normal end of file
171	                break;
172	            }
173	            const size_t n = static_cast<size_t>(got);
174	            if (!sink.consume(buffer.data() + filled, n)) {
175	                return false;
176	            }
177	            filled += n;
178	        }
179	        if (reachedEof) {
180	            break;
181	        }
182	    }
183	
184	    return sink.finish();
185	}
186	
187	// Streams every chunk through SHA-256 with fixed-size buffers, so memory use
188	// stays constant regardless of file size. On a processing failure it prints
189	// the reason (including pathArg) itself; after success hash() holds exactly
190	// kSha256Size bytes.
191	class Sha256StreamSink {
192	public:
193	    explicit Sha256StreamSink(const char* pathArg) : pathArg_(pathArg) {}
194	
195	    bool start() {
196	        ctx_.reset(EVP_MD_CTX_new());
197	        if (!ctx_ ||
198	            EVP_DigestInit_ex(ctx_.get(), EVP_sha256(), nullptr) != 1) {
199	            fail("SHA-256 initialization failed");
200	            return false;
201	        }
202	        return true;
203	    }
204	
205	    bool consume(const char* data, size_t size) {
206	        if (EVP_DigestUpdate(ctx_.get(), data, size) != 1) {
207	            fail("SHA-256 computation failed");
208	            return false;
209	        }
210	        return true;
211	    }
212	
213	    bool finish() {
214	        unsigned int hashLen = 0;
215	        if (EVP_DigestFinal_ex(ctx_.get(), hash_, &hashLen) != 1 ||
216	            hashLen != kSha256Size) {
217	            fail("SHA-256 computation failed");
218	            return false;
219	        }
220	        return true;
221	    }
222	
223	    const unsigned char* hash() const { return hash_; }
224	
225	private:
226	    void fail(const char* what) {
227	        std::cerr << "sealmark: " << what << " for '" << pathArg_ << "'\n";
228	    }
229	
230	    const char* pathArg_;
231	    std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx_{
232	        nullptr, &EVP_MD_CTX_free};
233	    unsigned char hash_[kSha256Size] = {};
234	};
235	
236	// Streaming parser for the strict single-block PEM structure used by key-id:
237	//
238	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
239	//   (base64 lines; no blank or whitespace-only lines) ...
240	//   -----END PUBLIC KEY-----
241	//   [ASCII ws]
242	//
243	// The BEGIN line must end in LF or CRLF, but the END marker needs no line
244	// terminator at all: once it is fully matched, EOF may follow immediately or
245	// any number of ASCII whitespace bytes -- the conventional trailing LF or
246	// CRLF included, but also spaces or tabs glued directly to the marker, with
247	// no requirement that the first such byte be a line feed.
248	//
249	// Bytes are fed straight from the read passes, chunk by chunk, and nothing is
250	// retained besides the fixed-size parser state and the decoded payload: the
251	// surrounding whitespace is merely classified and discarded, and each base64
252	// quantum is decoded the moment its fourth character arrives, so no base64
253	// text is ever accumulated. Memory use therefore depends on the size of the
254	// encoded public key itself, not on the amount of whitespace around the block
255	// or on the file size; no file-size limit is imposed.
256	//
257	// Anything outside the grammar above fails deterministically: non-whitespace
258	// outside the block, more than one block, any other PEM label (private keys,
259	// certificates, PKCS#1 RSA public keys, ...), malformed or truncated base64.
260	// finish() additionally verifies that the decoded payload is one complete,
261	// canonical DER SubjectPublicKeyInfo understood by the crypto library, so
262	// non-DER BER encodings and trailing bytes are rejected as well.
263	class PublicKeyPemSink {
264	public:
265	    explicit PublicKeyPemSink(const char* pathArg) : pathArg_(pathArg) {}
266	
267	    bool start() { return true; }
268	
269	    bool consume(const char* data, size_t size) {
270	        if (failed_) {
271	            return false;  // stay failed across the rest of the file
272	        }
273	        for (size_t i = 0; i < size; ++i) {
274	            if (!feed(static_cast<unsigned char>(data[i]))) {
275	                failed_ = true;
276	                reportInvalid();
277	                return false;
278	            }
279	        }
280	        return true;
281	    }
282	
283	    bool finish() {
284	        if (failed_) {
285	            return false;  // consume() already reported the reason
286	        }
287	        bool ok = false;
288	        switch (phase_) {
289	            case Phase::kEndMarker:
290	                // A fully matched END marker needs no trailing whitespace or
291	                // line feed at EOF; an unfinished match is a truncated marker.
292	                ok = markerMatched_ == kPemEnd.size();
293	                break;
294	            case Phase::kPostamble:
295	                // Complete marker already followed by at least one whitespace
296	                // byte; everything remaining was whitespace as well.
297	                ok = true;
298	                break;
299	            case Phase::kPreamble:       // empty or whitespace-only file
300	            case Phase::kBeginMarker:    // truncated BEGIN line
301	            case Phase::kBeginCr:        // CR in the header not followed by LF
302	            case Phase::kBodyLineStart:
303	            case Phase::kBodyData:
304	            case Phase::kBodyCr:         // truncated: no END line
305	                break;
306	        }
307	        if (ok) {
308	            ok = flushQuantumAtEnd() && validateSpkiDer();
309	        }
310	        if (!ok) {
311	            failed_ = true;
312	            reportInvalid();
313	        }
314	        return ok;
315	    }
316	
317	    // Valid only after finish() succeeded: the canonical SPKI DER.
318	    const std::vector<unsigned char>& spkiDer() const { return der_; }
319	
320	private:
321	    enum class Phase {
322	        kPreamble,
323	        kBeginMarker,
324	        kBeginCr,
325	        kBodyLineStart,
326	        kBodyData,
327	        kBodyCr,
328	        kEndMarker,
329	        kPostamble,
330	    };
331	
332	    bool feed(unsigned char c) {
333	        switch (phase_) {
334	            case Phase::kPreamble:
335	                if (isAsciiSpace(c)) {
336	                    return true;
337	                }
338	                if (c == static_cast<unsigned char>(kPemBegin[0])) {
339	                    markerMatched_ = 1;
340	                    phase_ = Phase::kBeginMarker;
341	                    return true;
342	                }
343	                return false;
344	
345	            case Phase::kBeginMarker:
346	                if (c == '\n') {
347	                    return markerMatched_ == kPemBegin.size() &&
348	                           beginComplete();
349	                }
350	                if (c == '\r') {
351	                    if (markerMatched_ != kPemBegin.size()) {
352	                        return false;
353	                    }
354	                    phase_ = Phase::kBeginCr;
355	                    return true;
356	                }
357	                if (markerMatched_ < kPemBegin.size() &&
358	                    c == static_cast<unsigned char>(kPemBegin[markerMatched_])) {
359	                    ++markerMatched_;
360	                    return true;
361	                }
362	                return false;
363	
364	            case Phase::kBeginCr:
365	                // A CR in the header is only legal as the CR of CRLF.
366	                return c == '\n' && beginComplete();
367	
368	            case Phase::kBodyLineStart:
369	                if (c == '-') {
370	                    markerMatched_ = 1;
371	                    phase_ = Phase::kEndMarker;
372	                    return true;
373	                }
374	                if (c == '\n') {
375	                    return false;  // no blank lines inside the block
376	                }
377	                if (isAsciiSpace(c)) {
378	                    return false;  // whitespace is allowed only around it
379	                }
380	                return feedBase64Data(c);
381	
382	            case Phase::kBodyData:
383	                if (c == '\n') {
384	                    if (lineEmpty_) {
385	                        return false;  // blank or whitespace-only line
386	                    }
387	                    lineEmpty_ = true;
388	                    phase_ = Phase::kBodyLineStart;
389	                    return true;
390	                }
391	                if (c == '\r') {
392	                    if (lineEmpty_) {
393	                        return false;
394	                    }
395	                    phase_ = Phase::kBodyCr;
396	                    return true;
397	                }
398	                if (isAsciiSpace(c)) {
399	                    return false;
400	                }
401	                return feedBase64Data(c);
402	
403	            case Phase::kBodyCr:
404	                // Bare CRs are not line separators: a CR must end with LF.
405	                if (c != '\n') {
406	                    return false;
407	                }
408	                lineEmpty_ = true;
409	                phase_ = Phase::kBodyLineStart;
410	                return true;
411	
412	            case Phase::kEndMarker:
413	                // While the marker is still incomplete its bytes must match
414	                // literally. A complete marker terminates the block outright:
415	                // LF/CRLF, spaces and tabs are all just postamble whitespace,
416	                // so the byte right after the final '-' need not be a line
417	                // feed. Whitespace inside a still-unfinished marker is not
418	                // part of the literal and fails like any other mismatch.
419	                if (markerMatched_ == kPemEnd.size()) {
420	                    if (isAsciiSpace(c)) {
421	                        return endComplete();
422	                    }
423	                    return false;
424	                }
425	                if (c == static_cast<unsigned char>(
426	                        kPemEnd[markerMatched_])) {
427	                    ++markerMatched_;
428	                    return true;
429	                }
430	                return false;
431	
432	            case Phase::kPostamble:
433	                // Everything still in the file must be ASCII whitespace; a
434	                // second block or any appended text is rejected, not ignored.
435	                return isAsciiSpace(c);
436	        }
437	        return false;
438	    }
439	
440	    bool beginComplete() {
441	        phase_ = Phase::kBodyLineStart;
442	        lineEmpty_ = true;
443	        return true;
444	    }
445	
446	    bool endComplete() {
447	        phase_ = Phase::kPostamble;
448	        return true;
449	    }
450	
451	    static int base64Value(unsigned char c) {
452	        if (c >= 'A' && c <= 'Z') return c - 'A';
453	        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
454	        if (c >= '0' && c <= '9') return c - '0' + 52;
455	        if (c == '+') return 62;
456	        if (c == '/') return 63;
457	        return -1;
458	    }
459	
460	    // Feeds one character of a payload line. '-' is deliberately outside the
461	    // alphabet (it starts the END marker, handled by the caller), so any other
462	    // PEM boundary fails here rather than being consumed. Decoding is strict
463	    // and canonical, quantum by quantum; padding is legal only as the
464	    // conventional "x=" / "xx==" tail of the stream, and its unused bits must
465	    // be zero. This mirrors the former whole-file decoder exactly.
466	    bool feedBase64Data(unsigned char c) {
467	        phase_ = Phase::kBodyData;
468	        lineEmpty_ = false;
469	
470	        quantum_[quantumLen_++] = c;
471	        if (quantumLen_ < 4) {
472	            return true;  // wait for the rest of the quantum
473	        }
474	        quantumLen_ = 0;
475	
476	        const int a = base64Value(quantum_[0]);
477	        const int b = base64Value(quantum_[1]);
478	        if (a < 0 || b < 0) {
479	            return false;
480	        }
481	
482	        const bool pad2 = quantum_[2] == '=';
483	        const bool pad3 = quantum_[3] == '=';
484	        if (sawPadding_) {
485	            return false;  // no complete quantum may follow a padded one
486	        }
487	
488	        if (pad2) {
489	            if (!pad3) {
490	                return false;  // '=' at position 2 requires one at position 3
491	            }
492	            if ((b & 0x0f) != 0) {
493	                return false;  // non-canonical: unused padding bits must be 0
494	            }
495	            der_.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
496	            sawPadding_ = true;
497	        } else {
498	            const int cv = base64Value(quantum_[2]);
499	            if (cv < 0) {
500	                return false;
501	            }
502	            if (pad3) {
503	                if ((cv & 0x03) != 0) {
504	                    return false;  // non-canonical: unused padding bits must be 0
505	                }
506	                der_.push_back(
507	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
508	                der_.push_back(static_cast<unsigned char>(
509	                    ((b & 0x0f) << 4) | (cv >> 2)));
510	                sawPadding_ = true;
511	            } else {
512	                const int d = base64Value(quantum_[3]);
513	                if (d < 0) {
514	                    return false;
515	                }
516	                der_.push_back(
517	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
518	                der_.push_back(static_cast<unsigned char>(
519	                    ((b & 0x0f) << 4) | (cv >> 2)));
520	                der_.push_back(static_cast<unsigned char>(
521	                    ((cv & 0x03) << 6) | d));
522	            }
523	        }
524	        return true;
525	    }
526	
527	    // At EOF the payload must have ended on a quantum boundary and must
528	    // decode to at least one byte.
529	    bool flushQuantumAtEnd() {
530	        if (quantumLen_ != 0 || der_.empty()) {
531	            return false;
532	        }
533	        return true;
534	    }
535	
536	    // Validates that the decoded payload is one complete SubjectPublicKeyInfo
537	    // DER structure covering every byte, understood by the crypto library, and
538	    // in canonical encoding. Re-encoding the parsed structure must reproduce
539	    // the payload byte for byte; that round trip rules out non-DER BER
540	    // encodings and other representations OpenSSL might otherwise accept. The
541	    // bytes hashed for the fingerprint are therefore the canonical SPKI DER,
542	    // so PEM line wrapping and line endings never influence the result.
543	    bool validateSpkiDer() {
544	        const unsigned char* p = der_.data();
545	        const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
546	            d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(der_.size()), nullptr,
547	                          nullptr),
548	            &EVP_PKEY_free);
549	        if (!pkey) {
550	            return false;
551	        }
552	        if (p - der_.data() != static_cast<ptrdiff_t>(der_.size())) {
553	            return false;  // trailing bytes after the SPKI structure
554	        }
555	
556	        const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
557	        if (encLen <= 0 || static_cast<size_t>(encLen) != der_.size()) {
558	            return false;
559	        }
560	        std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
561	        unsigned char* q = reencoded.data();
562	        if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != der_) {
563	            return false;  // non-canonical DER
564	        }
565	        return true;
566	    }
567	
568	    void reportInvalid() const {
569	        std::cerr << "sealmark: '" << pathArg_
570	                  << "' does not contain a single valid PEM-encoded "
571	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
572	    }
573	
574	    Phase phase_ = Phase::kPreamble;
575	    size_t markerMatched_ = 0;  // prefix length of the marker being matched
576	    bool lineEmpty_ = true;     // current body line has seen no data yet
577	    unsigned char quantum_[4] = {};
578	    size_t quantumLen_ = 0;
579	    bool sawPadding_ = false;  // a padded (final) quantum already occurred
580	    bool failed_ = false;
581	    const char* pathArg_ = nullptr;
582	    std::vector<unsigned char> der_;
583	};
584	
585	// Renders bytes as lowercase hexadecimal with no separators or prefix.
586	std::string toHexLower(const unsigned char* data, size_t size) {
587	    static constexpr char kHex[] = "0123456789abcdef";
588	    std::string out;
589	    out.reserve(2 * size);
590	    for (size_t i = 0; i < size; ++i) {
591	        out.push_back(kHex[data[i] >> 4]);
592	        out.push_back(kHex[data[i] & 0x0f]);
593	    }
594	    return out;
595	}
596	
597	int digestFile(const char* pathArg) {
598	    Sha256StreamSink sink(pathArg);
599	    if (!processFileChunks(pathArg, sink)) {
600	        return 1;
601	    }
602	
603	    std::cout << kDigestPrefix
604	              << toHexLower(sink.hash(), kSha256Size) << '\n';
605	    return 0;
606	}
607	
608	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
609	// characters: no missing prefix, no uppercase, no other algorithm names,
610	// no surrounding whitespace or trailing content.
611	bool isValidExpectedDigest(std::string_view digest) {
612	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
613	        return false;
614	    }
615	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
616	        return false;
617	    }
618	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
619	        const char c = digest[i];
620	        const bool isHex =
621	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
622	        if (!isHex) {
623	            return false;
624	        }
625	    }
626	    return true;
627	}
628	
629	int verifyDigestFile(const char* pathArg, std::string_view expected) {
630	    Sha256StreamSink sink(pathArg);
631	    if (!processFileChunks(pathArg, sink)) {
632	        return 1;
633	    }
634	
635	    std::string actual;
636	    actual.reserve(kDigestPrefix.size() + kDigestHexLen);
637	    actual.append(kDigestPrefix);
638	    actual.append(toHexLower(sink.hash(), kSha256Size));
639	
640	    if (actual == expected) {
641	        std::cout << "match\n";
642	        return 0;
643	    }
644	    std::cout << "mismatch\n";
645	    return 3;
646	}
647	
648	int keyIdFile(const char* pathArg) {
649	    PublicKeyPemSink sink(pathArg);
650	    if (!processFileChunks(pathArg, sink)) {
651	        return 1;
652	    }
653	
654	    const std::vector<unsigned char>& spkiDer = sink.spkiDer();
655	    unsigned char hash[kSha256Size];
656	    unsigned int hashLen = 0;
657	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
658	                   EVP_sha256(), nullptr) != 1 ||
659	        hashLen != kSha256Size) {
660	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
661	                  << "'\n";
662	        return 1;
663	    }
664	
665	    std::cout << kSpkiFingerprintPrefix
666	              << toHexLower(hash, kSha256Size) << '\n';
667	    return 0;
668	}
669	
670	}  // namespace
671	
672	int main(int argc, char* argv[]) {
673	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
674	        std::cout << "sealmark 0.1.0\n";
675	        return 0;
676	    }
677	    if (argc == 3 && std::string_view(argv[1]) == "digest") {
678	        if (argv[2][0] == '\0') {
679	            return printUsage();
680	        }
681	        return digestFile(argv[2]);
682	    }
683	    if (argc == 3 && std::string_view(argv[1]) == "key-id") {
684	        if (argv[2][0] == '\0') {
685	            return printUsage();
686	        }
687	        return keyIdFile(argv[2]);
688	    }
689	    if (argc == 4 && std::string_view(argv[1]) == "verify-digest") {
690	        // Validate every argument before touching the file so that a bad
691	        // path and a malformed digest together still report a usage error.
692	        if (argv[2][0] == '\0' || !isValidExpectedDigest(argv[3])) {
693	            return printUsage();
694	        }
695	        return verifyDigestFile(argv[2], argv[3]);
696	    }
697	    return printUsage();
698	}
