static struct {
    int valid;
    dev_t dev;
    ino_t ino;
    struct directive directives[MAX_DIRECTIVES];
    size_t directive_count;
    size_t next;                 /* next directive to apply */
    int stuck_eio;               /* a DIR_EIO directive has fired */
    unsigned long eintr_injected;
